  FUNCTION lines_by_kind RETURN SYS_REFCURSOR IS
    l_pell_pivot_cols VARCHAR2(4000);
    l_pell_pivot_sql  VARCHAR2(32767);
    l_pell_pivot_cur  SYS_REFCURSOR;
  BEGIN
    SELECT LISTAGG('''' || kind || ''' AS "' || kind || '"', ', ')
             WITHIN GROUP (ORDER BY kind)
      INTO l_pell_pivot_cols
      FROM (SELECT DISTINCT kind FROM (
    select name,
             replace(type, ' ', '_') as kind,
             count(*) as line_count
        from user_source
       group by name, type
      )) WHERE kind IS NOT NULL;
    l_pell_pivot_sql :=
      'SELECT * FROM (' ||
      'select name,
             replace(type, '' '', ''_'') as kind,
             count(*) as line_count
        from user_source
       group by name, type' ||
      ') PIVOT (SUM(line_count) FOR kind IN (' ||
      l_pell_pivot_cols ||
      '))';
    OPEN l_pell_pivot_cur FOR l_pell_pivot_sql;
    RETURN l_pell_pivot_cur;
  END lines_by_kind;

